    /**
     * Method to retrieve the Facility via FacilityFetchOneSummary
     * @param 	summary FacilityFetchOneSummary 
     * @return 	FacilityFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Facility getFacility( FacilityFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "FacilityFetchOneSummary arg cannot be null" );
    	
    	Facility entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Facility
        	// --------------------------------------
        	CompletableFuture<Facility> futureEntity = queryGateway.query(new FindFacilityQuery( new LoadFacilityFilter( summary.getFacilityId() ) ), ResponseTypes.instanceOf(Facility.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Facility with id " + summary.getFacilityId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


